package com.ruoyi.boost;
import java.util.*;import java.util.concurrent.*;import javax.sql.DataSource;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.test.context.ContextConfiguration;
import static org.junit.jupiter.api.Assertions.*;import static com.ruoyi.boost.BoostDb.*;
@EnabledIfEnvironmentVariable(named="BOOST_REWARDS_TEST_DB_URL",matches=".+")
@ContextConfiguration(classes=BoostRewardsMySqlTest.MySqlConfig.class,inheritLocations=false)
class BoostRewardsMySqlTest extends BoostRewardsTest {
 @Configuration static class MySqlConfig extends BoostRewardsTest.Config {@Override @Bean DataSource dataSource(){String url=System.getenv("BOOST_REWARDS_TEST_DB_URL");if(url==null||!url.matches("jdbc:mysql://(127\\.0\\.0\\.1|localhost)(:[0-9]+)?/boost_verify_[0-9]+\\?.*"))throw new IllegalArgumentException("Only an owned local rewards test DB is allowed");DataSource d=new DriverManagerDataSource(url,System.getenv("BOOST_REWARDS_TEST_DB_USER"),System.getenv("BOOST_REWARDS_TEST_DB_PASSWORD"));initialize(d);return d;}@Override @Bean BoostDb db(JdbcTemplate j){return new ControlledDb(j);}}
 static class ControlledDb extends BoostDb {volatile long first,second;volatile boolean armed,shipping;CountDownLatch drawLocked,editBoundary,release,shipBoundary;ControlledDb(JdbcTemplate j){super(j);}void arm(long one,long two){first=one;second=two;drawLocked=new CountDownLatch(1);editBoundary=new CountDownLatch(1);release=new CountDownLatch(1);armed=true;}void armShipping(){shipBoundary=new CountDownLatch(1);release=new CountDownLatch(1);shipping=true;}void pause(){try{assertTrue(release.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){throw new AssertionError(e);}}@Override public Map<String,Object>one(String sql,Object...args){if(shipping&&Thread.currentThread().getName().equals("reward-ship")&&sql.equals("SELECT id FROM boost_member WHERE id=? FOR UPDATE")){shipBoundary.countDown();pause();}if(armed&&Thread.currentThread().getName().equals("reward-edit")&&sql.equals("SELECT id FROM boost_reward_goods WHERE id=? FOR UPDATE")&&((Number)args[0]).longValue()==first){editBoundary.countDown();pause();}Map<String,Object>r=super.one(sql,args);if(shipping&&Thread.currentThread().getName().equals("reward-ship")&&sql.equals("SELECT * FROM boost_reward_order WHERE id=? FOR UPDATE")){shipBoundary.countDown();pause();}if(armed&&Thread.currentThread().getName().equals("reward-draw")&&sql.equals("SELECT * FROM boost_reward_goods WHERE id=? FOR UPDATE")&&((Number)args[0]).longValue()==first){drawLocked.countDown();pause();}return r;}@Override public int run(String sql,Object...args){int result=super.run(sql,args);if(armed&&Thread.currentThread().getName().equals("reward-edit")&&sql.startsWith("INSERT INTO boost_reward_prize")&&args[1]!=null&&((Number)args[1]).longValue()==second){editBoundary.countDown();pause();}return result;}}
 @Test void concurrentMembersCannotRedeemLastStockTwice()throws Exception{long g=product("PHYSICAL",1);grant(member,100);grant(other,100);CountDownLatch start=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<Boolean>>results=new ArrayList<>();for(long who:List.of(member,other))results.add(pool.submit(()->{start.await();try{rewards.redeem(who,g,body());return true;}catch(BoostException e){return false;}}));start.countDown();int success=0;for(Future<Boolean>f:results)if(f.get(15,TimeUnit.SECONDS))success++;assertEquals(1,success);assertEquals(0,num(rewards.good(g,true),"stock"));assertEquals(1,db.count("SELECT COUNT(*) FROM boost_reward_order WHERE goods_id=?",g));assertEquals(190,db.count("SELECT SUM(balance) FROM boost_points_account WHERE member_id IN (?,?)",member,other));}finally{pool.shutdownNow();assertTrue(pool.awaitTermination(10,TimeUnit.SECONDS));}}
 @Test void concurrentSameKeyFiveDrawChargesExactlyOnce()throws Exception{long g=product("PHYSICAL",100),a=activity(List.of(map("goodsId",g,"weight",1),map("goodsId",null,"weight",1)));grant(member,100);Map<String,Object>b=body();b.put("count",5);b.put("expectedPointsCost",2);CountDownLatch start=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<Map<String,Object>>>results=new ArrayList<>();for(int i=0;i<2;i++)results.add(pool.submit(()->{start.await();return (Map<String,Object>)rewards.draw(member,a,b);}));start.countDown();Map<String,Object>one=results.get(0).get(15,TimeUnit.SECONDS),two=results.get(1).get(15,TimeUnit.SECONDS);assertEquals(one.get("id"),two.get("id"));assertEquals(one.get("results"),two.get("results"));assertEquals(90,balance());assertEquals(1,db.count("SELECT COUNT(*) FROM boost_reward_draw WHERE member_id=?",member));assertEquals(1,db.count("SELECT COUNT(*) FROM boost_points_entry WHERE member_id=? AND kind='DRAW'",member));}finally{pool.shutdownNow();assertTrue(pool.awaitTermination(10,TimeUnit.SECONDS));}}
 @Test void editingReversePrizeOrderDuringAnotherActivityDrawHasNoDeadlock()throws Exception{long first=product("PHYSICAL",100),second=product("PHYSICAL",100),a=activity(List.of(map("goodsId",first,"weight",1),map("goodsId",second,"weight",1))),b=activity(List.of(map("goodsId",second,"weight",1),map("goodsId",first,"weight",1)));grant(member,100);Map<String,Object>edit=new HashMap<>(rewards.activity(b,null,true));edit.put("prizes",List.of(map("goodsId",second,"weight",2),map("goodsId",first,"weight",1)));Map<String,Object>body=body();body.put("count",1);body.put("expectedPointsCost",2);ControlledDb gate=(ControlledDb)db;gate.arm(first,second);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?>draw=pool.submit(()->{Thread.currentThread().setName("reward-draw");return rewards.draw(member,a,body);});assertTrue(gate.drawLocked.await(10,TimeUnit.SECONDS));Future<?>update=pool.submit(()->{Thread.currentThread().setName("reward-edit");return rewards.saveActivity(1,b,edit);});assertTrue(gate.editBoundary.await(10,TimeUnit.SECONDS));gate.release.countDown();draw.get(15,TimeUnit.SECONDS);update.get(15,TimeUnit.SECONDS);assertEquals(98,balance());assertEquals(2,num(rewards.activity(b,null,true),"revision"));}finally{gate.armed=false;gate.release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(10,TimeUnit.SECONDS));}}
 @Test void shippingAndOwnerAddressUpdateUseConsistentMemberOrderLocks()throws Exception{long g=product("PHYSICAL",1);grant(member,100);long id=num((Map<String,Object>)rewards.redeem(member,g,body()),"id");Map<String,Object>address=map("recipient","测试收件人","phone","13800000000","address","测试省测试市测试区测试街道1号");rewards.address(member,id,address);ControlledDb gate=(ControlledDb)db;gate.armShipping();CountDownLatch ownerLocked=new CountDownLatch(1),ownerRelease=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?>owner=pool.submit(()->new org.springframework.transaction.support.TransactionTemplate(tx).execute(status->{db.activeMember(member);ownerLocked.countDown();try{assertTrue(ownerRelease.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){throw new AssertionError(e);}return rewards.address(member,id,address);}));assertTrue(ownerLocked.await(10,TimeUnit.SECONDS));Future<?>ship=pool.submit(()->{Thread.currentThread().setName("reward-ship");return rewards.ship(1,id,map("carrier","测试物流","trackingNo","LOCKTEST001"));});assertTrue(gate.shipBoundary.await(10,TimeUnit.SECONDS));ownerRelease.countDown();gate.release.countDown();owner.get(15,TimeUnit.SECONDS);ship.get(15,TimeUnit.SECONDS);assertEquals("SHIPPED",str(rewards.detail(member,id),"status"));assertEquals(1,db.count("SELECT COUNT(*) FROM boost_audit WHERE action='rewards:ship' AND target_id=?",id));}finally{gate.shipping=false;ownerRelease.countDown();gate.release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(10,TimeUnit.SECONDS));}}
}
